// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
        c.OpenToThePublic();
        c.AdjustBetAmounts(100);
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(this));
        vm.assume(amount <= type(uint256).max);

        uint256 beforeLimit = c.currentBetLimit();

        vm.prank(actor);
        try c.AdjustBetAmounts(amount) {
            assertTrue(c.currentBetLimit() == beforeLimit);
        } catch {
            assertTrue(c.currentBetLimit() == beforeLimit);
        }
    }
}
